package com.amora.app;
import android.content.*;
import android.app.*;
import android.webkit.*;
import android.os.*;
import android.speech.tts.*;
import org.json.*;
import java.util.*;
public class NativeBridge {
 static android.media.MediaPlayer player;static java.io.File voiceFile;
 static byte[] exportBytes;static String exportName,exportMime;
 final Context context;final WebView web;static TextToSpeech tts;static String pending="";static final Handler main=new Handler(Looper.getMainLooper());
 NativeBridge(Context c,WebView w){context=c;web=w;}
 static void event(String key,Object value){try{JSONObject d=new JSONObject().put(key,value);pending=d.toString();main.post(()->{if("speaking".equals(key))OverlayService.speaking(Boolean.TRUE.equals(value));for(WebView w:new ArrayList<>(AmoraWeb.views))flush(w);});}catch(Exception ignored){}}
 static void flush(WebView w){if(pending.isEmpty())return;String data=pending;w.evaluateJavascript("window.__amoraPending="+data+";window.dispatchEvent(new CustomEvent('amora-native',{detail:"+data+"}))",null);}
 void launch(String action){main.post(()->{boolean fromOverlay=!(context instanceof Activity);if(fromOverlay)OverlayService.hidePanel();context.startActivity(new Intent(context,MainActivity.class).setAction(action).putExtra("fromOverlay",fromOverlay).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));});}
 @JavascriptInterface public void overlay(boolean on){if(on)launch("amora.overlay");else context.stopService(new Intent(context,OverlayService.class));}
 @JavascriptInterface public void openApp(String route){if(!java.util.Arrays.asList("home","chat","expenses","camera","album","files","apps","lilith","games","paint","notes","agenda","history","ideas","lists","map").contains(route))return;main.post(()->{context.startActivity(new Intent(context,MainActivity.class).putExtra("route",route).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP));OverlayService.hidePanel();});}
 @JavascriptInterface public void configureOverlay(String json){try{JSONArray input=new JSONObject(json).getJSONArray("actions"),valid=new JSONArray();for(int i=0;i<input.length();i++){String action=input.getString(i);if(Arrays.asList("lilith","chat","apps","camera").contains(action))valid.put(action);}context.getSharedPreferences("amora",0).edit().putString("overlayActions",valid.toString()).apply();main.post(()->{if(OverlayService.active!=null)OverlayService.active.refreshActions();});}catch(Exception ignored){}}
 @JavascriptInterface public void background(){main.post(()->{if(context instanceof Activity)((Activity)context).moveTaskToBack(true);});}
 @JavascriptInterface public void openExternal(String url){if(url==null||url.length()>8000)return;android.net.Uri uri=android.net.Uri.parse(url);if(!"https".equals(uri.getScheme()))return;main.post(()->{try{OverlayService.hidePanel();context.startActivity(new Intent(Intent.ACTION_VIEW,uri).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){event("error","Não foi possível abrir o navegador.");}});}
 @JavascriptInterface public void saveBinary(String name,String mime,String base64){if(base64==null||base64.length()>28000000||mime==null||!mime.matches("[a-zA-Z0-9.+-]+/[a-zA-Z0-9.+-]+"))return;try{byte[] bytes=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);if(bytes.length>20971520)return;main.post(()->{if(exportBytes!=null){event("error","Conclua o salvamento anterior.");return;}exportBytes=bytes;exportName=name==null?"Amora":name.replaceAll("[^a-zA-Z0-9._-]","_");exportMime=mime;launch("amora.save");});}catch(Exception e){event("error","Arquivo inválido.");}}
 static void stopPlayer(){if(player!=null){player.release();player=null;}if(voiceFile!=null){voiceFile.delete();voiceFile=null;}}
 @JavascriptInterface public void playVoice(String base64){if(base64==null||base64.length()>12000000)return;main.post(()->{try{stopPlayer();byte[] bytes=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);voiceFile=java.io.File.createTempFile("lilith-",".mp3",context.getCacheDir());try(java.io.FileOutputStream out=new java.io.FileOutputStream(voiceFile)){out.write(bytes);}player=new android.media.MediaPlayer();player.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());player.setDataSource(voiceFile.getAbsolutePath());player.setOnPreparedListener(m->{m.start();event("speaking",true);});player.setOnCompletionListener(m->{stopPlayer();event("speaking",false);});player.setOnErrorListener((m,w,e)->{stopPlayer();event("speaking",false);event("error","Não foi possível reproduzir a voz.");return true;});player.prepareAsync();}catch(Exception e){stopPlayer();event("speaking",false);event("error","Não foi possível reproduzir a voz.");}});}
 @JavascriptInterface public void closeOverlay(){main.post(()->OverlayService.hidePanel());}
 @JavascriptInterface public void saveFile(String name,String mime,String content){if(name==null||content==null||content.length()>5000000||!Arrays.asList("text/csv","image/svg+xml","application/json","text/calendar").contains(mime))return;main.post(()->{if(exportBytes!=null){event("error","Conclua ou cancele o salvamento anterior.");return;}exportBytes=content.getBytes(java.nio.charset.StandardCharsets.UTF_8);exportName=name.replaceAll("[^a-zA-Z0-9._-]","_");exportMime=mime;launch("amora.save");});}
 @JavascriptInterface public void capture(){launch("amora.capture");}
 @JavascriptInterface public void listen(){launch("amora.voice");}
 @JavascriptInterface public void stopAudio(){main.post(()->{if(tts!=null)tts.stop();stopPlayer();event("speaking",false);});}
 @JavascriptInterface public void speak(String text){if(text==null||text.length()>15000)return;main.post(()->{if(tts==null){tts=new TextToSpeech(context.getApplicationContext(),status->{if(status==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("pt","BR"));say(text);}});}else say(text);});}
 static void say(String text){tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){event("speaking",true);}public void onDone(String id){event("speaking",false);}public void onError(String id){event("speaking",false);}});tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"lilith");}
 @JavascriptInterface public void reminders(String json){try{if(json.length()>40000)return;ReminderReceiver.schedule(context,new JSONArray(json));if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)launch("amora.permissions");}catch(Exception e){event("error","Não foi possível agendar os lembretes.");}}
 @JavascriptInterface public void clearSession(){main.post(()->{context.stopService(new Intent(context,OverlayService.class));context.stopService(new Intent(context,CaptureService.class));stopAudio();pending="";exportBytes=null;try{ReminderReceiver.schedule(context,new JSONArray());}catch(Exception ignored){}});}
 public static Notification notification(Context c,String channel,String title,String text,PendingIntent stop){NotificationManager m=c.getSystemService(NotificationManager.class);m.createNotificationChannel(new NotificationChannel(channel,title,NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(c,channel).setSmallIcon(R.drawable.amora_icon).setContentTitle(title).setContentText(text).setContentIntent(open).setOngoing(true);if(stop!=null)b.addAction(new Notification.Action.Builder(null,"Parar",stop).build());return b.build();}
}
